use std::{fs,path::Path,process::Command};
type R<T>=Result<T,Box<dyn std::error::Error>>;
fn main()->R<()>{let mut names=vec![];for e in fs::read_dir(".")?{let e=e?;let n=e.file_name().to_string_lossy().to_string();if !e.file_type()?.is_file()||n.ends_with(".exe")||n.ends_with(".pdb")||n.starts_with("publicacion-")||n.starts_with("modelo-")||n.starts_with("calidad-")||["TRAZA-SEGMENTO-04.tar.gz","preparar-custodia.rs","listar-entrega.rs","MANIFIESTO-ENTREGA.tsv","LISTA-ENTREGA.tsv"].contains(&n.as_str()){continue}names.push(n)}for e in fs::read_dir("trazas-mcp")?{let e=e?;if e.file_type()?.is_file(){names.push(format!("trazas-mcp/{}",e.file_name().to_string_lossy()));}}names.sort();let mut manifest=String::from("sha256\tbytes\tarchivo\n");for batch in names.chunks(16){let o=Command::new("./custodia-final-v7.exe").arg("hash").args(batch).output()?;if !o.status.success(){return Err("Cálculo de huellas no conforme".into())}manifest.push_str(&String::from_utf8(o.stdout)?);}fs::write("MANIFIESTO-ENTREGA.tsv",manifest)?;names.push("MANIFIESTO-ENTREGA.tsv".into());let list=names.iter().map(|n|format!("{n}\trespuestas-ejecucion/QWEN80-Q4K-ONECLOUD-20260929/entrega-09/{n}\n")).collect::<String>();fs::write("LISTA-ENTREGA.tsv",list)?;for n in &names{assert!(Path::new(n).exists())}println!("LISTA_COMPROBADA {} archivos",names.len());Ok(())}
